-- Generated by scripts/feature-post.mjs. Makes "ai-assistant-lead-source-option" the featured Industry LoogoBlog
-- post. Clear first, then set, so posts_one_featured never sees two rows.
UPDATE "posts" SET "featured" = false WHERE "featured" AND "slug" <> 'ai-assistant-lead-source-option';
UPDATE "posts" SET "featured" = true WHERE "slug" = 'ai-assistant-lead-source-option' AND "status" = 'published';
